package app.bible.feed

import app.bible.core.VerseId

/** All 31,102 KJV verses as grouper units (id, length, boundary weight), generated by :pipeline:importKjv. */
object KjvFixture {
    val units: List<VerseUnit> by lazy {
        val stream = checkNotNull(javaClass.getResourceAsStream("/kjv-units.tsv")) { "Run ./gradlew :pipeline:importKjv" }
        stream.bufferedReader().readLines().map { line ->
            val (id, chars, w) = line.split('\t')
            VerseUnit(VerseId(id.toInt()), chars.toInt(), w.toInt())
        }
    }

    fun range(from: VerseId, to: VerseId): List<VerseUnit> = units.filter { it.id >= from && it.id <= to }
}
